package com.colovision.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="patients") public class Patient { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="patient_id",unique=true) public String patientId; public String name; @Column(columnDefinition="TEXT") public String address; public int age; public String gender; public String contact; @Column(name="photo_path") public String photoPath; @Column(name="created_by") public Long createdBy; @Column(name="created_at") public Instant createdAt=Instant.now(); @JsonIgnore @OneToMany(mappedBy="patient",cascade=CascadeType.ALL,orphanRemoval=true) public List<Prediction> predictions=new ArrayList<>(); }
